304	    /** The sheet's claims, newest first. */
305	    @Transactional(readOnly = true)
306	    public List<Claim> list(String sheetId) {
307	        sheets.today(sheetId); // the sheet must exist
308	        return claims.findBySheetIdOrderByIdDesc(sheetId);
