311	    /** Add a claim for a person; a claim without a date is dated the sheet's today. One dated in a closed period
312	     * is refused, and so is a correction that does not name a settled claim of the same person. */
313	    @Transactional
314	    public Claim add(String user, String sheetId, Long personId, BigDecimal amount, LocalDate date, String note,
315	            String corrects) {
316	        LocalDate today = sheets.today(sheetId);
317	        Person person = requirePerson(sheetId, personId);
318	        requireNotRetired(person, date != null ? date : today);
319	        requireOpenPeriod(sheetId, date != null ? date : today);
320	        String corrected = correctedBy(sheetId, personId, amount, corrects);
321	        Snapshot before = rollup.snapshot(sheetId);
322	        LocalDate dated = date != null ? date : today;
323	        // The due-by is fixed now, from the terms in force on the claim's date for the grade the person has then.
324	        LocalDate dueBy = dated.plusDays(settings.termsFor(sheetId, person.gradeOn(dated), dated));
325	        Claim fresh = new Claim(sheetId, personId, amount, dated, dueBy, noteOf(note));
326	        fresh.setCorrects(corrected);
327	        Claim claim = claims.saveAndFlush(fresh);
328	        logStatus(user, today, claim, person);
329	        claims.flush();
330	        audit.recordOnCommit(entry("CLAIM_ADDED", user, person, claim));
331	        rollup.recordChanges(user, sheetId, before);
332	        return claim;
333	    }
334	
335	    /** Edit a claim; only a draft can be edited (an open claim is voided and added again instead), and one dated
336	     * in a closed period, or that would be, is refused, as is a correction that does not name a settled claim of
337	     * the same person. */
338	    @Transactional
339	    public Claim update(String user, String sheetId, Long id, BigDecimal amount, LocalDate date, String note,
340	            String corrects) {
341	        LocalDate today = sheets.today(sheetId);
342	        Claim claim = claims.findByIdAndSheetId(id, sheetId)
343	                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such claim."));
344	        if (claim.getStatus() != ClaimStatus.DRAFT) {
345	            throw new ResponseStatusException(HttpStatus.CONFLICT, "Only a draft claim can be edited.");
346	        }
347	        requireOpenPeriod(sheetId, claim.getDate());
348	        requireOpenPeriod(sheetId, date != null ? date : today);
349	        requireNotRetired(requirePerson(sheetId, claim.getPersonId()), date != null ? date : today);
350	        String corrected = correctedBy(sheetId, claim.getPersonId(), amount, corrects);
351	        Snapshot before = rollup.snapshot(sheetId);
352	        claim.setAmount(amount);
353	        claim.setCorrects(corrected);
354	        claim.setDate(date != null ? date : today);
355	        claim.setNote(noteOf(note));
356	        claims.flush();
357	        audit.recordOnCommit(entry("CLAIM_EDITED", user, requirePerson(sheetId, claim.getPersonId()), claim));
358	        rollup.recordChanges(user, sheetId, before);
359	        return claim;
360	    }
361	
362	    /** Move a claim to another status; a change its status does not allow, or of a claim dated in a closed
363	     * period, is refused. A settle by a clerk of a claim whose due is above the clerk limit sends it PENDING a
364	     * steward instead. */
365	    @Transactional
366	    public Claim changeStatus(String user, String sheetId, Long id, ClaimStatus next) {
367	        sheets.today(sheetId); // the sheet must exist
368	        // Locking the sheet before taking the number opens claims one at a time; a refused open rolls back
369	        // and gives the number back.
370	        if (next == ClaimStatus.OPEN) {
371	            sheets.lock(sheetId);
372	        }
373	        Claim claim = claims.findByIdAndSheetId(id, sheetId)
374	                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such claim."));
375	        String number = next == ClaimStatus.OPEN ? nextNumber(sheetId, claim) : null;
376	        requireOpenPeriod(sheetId, claim.getDate());
377	        if (!claim.getStatus().canBecome(next)) {
378	            throw new ResponseStatusException(HttpStatus.CONFLICT,
379	                    "A " + claim.getStatus() + " claim cannot become " + next + ".");
380	        }
381	        // Four eyes: whoever opened a claim cannot also settle it.
382	        if (next == ClaimStatus.SETTLED && user.equals(claim.getOpenedBy())) {
383	            throw new ResponseStatusException(HttpStatus.FORBIDDEN, "The user who opened a claim cannot settle it.");
384	        }
385	        Person person = requirePerson(sheetId, claim.getPersonId());
386	        BigDecimal due = rollup.dueOf(claim, person);
387	        // A clerk settles only a claim whose due is within the sheet's clerk limit; above it, a steward must
388	        // approve it.
389	        if (next == ClaimStatus.SETTLED && !settings.maySettle(sheetId, user, due)) {
390	            next = ClaimStatus.PENDING;
391	        }
392	        Snapshot before = rollup.snapshot(sheetId);
393	        claim.setStatus(next);
394	        if (next == ClaimStatus.OPEN) {
395	            claim.setNumber(number);
396	            claim.setOpenedBy(user);
397	        }
398	        // A voided claim's line carries the number it had.
399	        String entry = entry(EVENTS.get(next), user, person, claim);
400	        if (next == ClaimStatus.SETTLED) {
401	            // Settling fixes the due at the figure the claim has: the one its last statement bound it to, else
402	            // the rate its grade has on its date; with no figure it stays live. The late charge it has (taken
403	            // while it is still OPEN) is frozen in.
404	            entry += settle(claim, due);
405	        }
406	        logStatus(user, sheets.today(sheetId), claim, person);
407	        claims.flush();
408	        audit.recordOnCommit(entry);
409	        rollup.recordChanges(user, sheetId, before);
410	        return claim;
411	    }
412	
413	    /** A steward approves a PENDING claim: it is SETTLED at the due it has now, its live figure with any late
414	     * charge, frozen. The user who opened it cannot approve it. */
415	    @Transactional
416	    public Claim approve(String user, String sheetId, Long id) {
417	        Claim claim = requirePending(user, sheetId, id);
418	        if (user.equals(claim.getOpenedBy())) {
419	            throw new ResponseStatusException(HttpStatus.FORBIDDEN, "The user who opened a claim cannot approve it.");
420	        }
421	        Person person = requirePerson(sheetId, claim.getPersonId());
422	        Snapshot before = rollup.snapshot(sheetId);
423	        BigDecimal due = rollup.dueOf(claim, person);
424	        claim.setStatus(ClaimStatus.SETTLED);
425	        String entry = entry("CLAIM_APPROVED", user, person, claim) + settle(claim, due);
426	        logStatus(user, sheets.today(sheetId), claim, person);
427	        claims.flush();
428	        audit.recordOnCommit(entry);
429	        rollup.recordChanges(user, sheetId, before);
430	        return claim;
431	    }
432	
433	    /** A steward re-settles a SETTLED claim: it is frozen again at the figure it would have today as an OPEN
434	     * claim bound by no statement, at today's rates, grades, floor and late charge. Refused for anyone else, a
435	     * claim of any other status, or one dated in a closed period. */
436	    @Transactional
437	    public Claim resettle(String user, String sheetId, Long id) {
438	        sheets.today(sheetId); // the sheet must exist
439	        Claim claim = claims.findByIdAndSheetId(id, sheetId)
440	                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such claim."));
441	        requireOpenPeriod(sheetId, claim.getDate());
442	        if (claim.getStatus() != ClaimStatus.SETTLED) {
443	            throw new ResponseStatusException(HttpStatus.CONFLICT, "Only a SETTLED claim can be re-settled.");
444	        }
445	        settings.requireSteward(sheetId, user);
446	        Person person = requirePerson(sheetId, claim.getPersonId());
447	        Snapshot before = rollup.snapshot(sheetId);
448	        BigDecimal old = rollup.dueOf(claim, person);
449	        BigDecimal now = rollup.openDueOf(claim, person);
450	        claim.setSettledDue(now);
451	        logStatus(user, sheets.today(sheetId), claim, person);
452	        claims.flush();
453	        audit.recordOnCommit(entry("CLAIM_RESETTLED", user, person, claim) + " old=" + figure(old) + " new="
454	                + figure(now));
455	        rollup.recordChanges(user, sheetId, before);
456	        return claim;
457	    }
458	
459	    /** A figure with two decimals, or n/a. */
460	    private static String figure(BigDecimal due) {
461	        return due != null ? due.setScale(2).toPlainString() : "n/a";
462	    }
463	
464	    /** A steward rejects a PENDING claim with a reason: it is OPEN again, bound again by its person's last
465	     * statement if that statement included it. */
466	    @Transactional
467	    public Claim reject(String user, String sheetId, Long id, String reason) {
468	        Claim claim = requirePending(user, sheetId, id);
469	        Person person = requirePerson(sheetId, claim.getPersonId());
470	        Snapshot before = rollup.snapshot(sheetId);
471	        claim.setStatus(ClaimStatus.OPEN);
472	        logStatus(user, sheets.today(sheetId), claim, person);
473	        claims.flush();
474	        audit.recordOnCommit(entry("CLAIM_REJECTED", user, person, claim) + " reason=" + reason.trim());
475	        rollup.recordChanges(user, sheetId, before);
476	        return claim;
477	    }
478	
479	    /** A steward moves a DRAFT, OPEN or PENDING claim to another person on the sheet. It keeps its number and
480	     * date but loses any figure a statement bound it to: it is live again until its new person's next statement.
481	     * One dated in a closed period, a correction (which names a settled claim of its own person), or one dated
482	     * after its new person is retired, is refused. */
483	    @Transactional
484	    public Claim reassign(String user, String sheetId, Long id, Long toPersonId) {
485	        sheets.today(sheetId); // the sheet must exist
486	        Claim claim = claims.findByIdAndSheetId(id, sheetId)
487	                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such claim."));
488	        settings.requireSteward(sheetId, user);
489	        requireOpenPeriod(sheetId, claim.getDate());
490	        if (claim.getStatus() != ClaimStatus.DRAFT && !claim.getStatus().isOpen()) {
491	            throw new ResponseStatusException(HttpStatus.CONFLICT,
492	                    "A " + claim.getStatus() + " claim cannot be moved.");
493	        }
494	        if (claim.isCorrection()) {
495	            throw new ResponseStatusException(HttpStatus.CONFLICT, "A correction cannot be moved.");
496	        }
497	        Person from = requirePerson(sheetId, claim.getPersonId());
498	        Person to = requirePerson(sheetId, toPersonId);
499	        if (from.getId().equals(to.getId())) {
500	            throw new ResponseStatusException(HttpStatus.BAD_REQUEST, "The claim is already that person's.");
501	        }
502	        if (to.retiredOn(claim.getDate())) {
503	            throw new ResponseStatusException(HttpStatus.GONE,
504	                    to.getName() + " is retired from " + to.getRetiredFrom() + ".");
505	        }
506	        Snapshot before = rollup.snapshot(sheetId);
507	        claim.setPersonId(to.getId());
508	        claim.unbind();
509	        claims.flush();
510	        audit.recordOnCommit(entry("CLAIM_REASSIGNED", user, to, claim) + " from=" + from.getName() + " to="
511	                + to.getName());
512	        rollup.recordChanges(user, sheetId, before);
513	        return claim;
514	    }
515	
516	    /** The PENDING claim a steward acts on; refused when it is not on the sheet, not PENDING, dated in a closed
517	     * period, or the user is not a steward. */
518	    private Claim requirePending(String user, String sheetId, Long id) {
519	        sheets.today(sheetId); // the sheet must exist
520	        Claim claim = claims.findByIdAndSheetId(id, sheetId)
521	                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such claim."));
522	        requireOpenPeriod(sheetId, claim.getDate());
523	        if (claim.getStatus() != ClaimStatus.PENDING) {
524	            throw new ResponseStatusException(HttpStatus.CONFLICT, "Only a PENDING claim can be approved or rejected.");
525	        }
526	        settings.requireSteward(sheetId, user);
527	        return claim;
528	    }
529	
530	    /** Log the status a claim has now, by the user on the sheet's today, with its due as computed now. */
531	    private void logStatus(String user, LocalDate today, Claim claim, Person person) {
532	        BigDecimal due = rollup.dueOf(claim, person);
533	        claim.logStatus(user, today, due != null ? due.setScale(2).toPlainString() : "n/a");
534	    }
535	
536	    /** Fix a claim's due at the given figure (none stays live), giving the end of its audit line. */
537	    private static String settle(Claim claim, BigDecimal due) {
538	        claim.setSettledDue(due);
539	        return " due=" + (due != null ? due.toPlainString() : "n/a");
540	    }
541	
542	    /** What opening (or settling) claims together did: how many went through and were refused, and the claims
543	     * that went through. */
544	    public record OpenedAll(int opened, int refused, List<Claim> claims) {}
545	
546	    /** Open the given claims of the sheet one at a time, in list order: people in the order they were added,
547	     * each one's claims newest first. Each is opened, and numbered, as {@link #changeStatus} would open it on its
548	     * own; one that cannot be opened (or is not on the sheet) is refused and left as it is. */
549	    public OpenedAll openAll(String user, String sheetId, List<Long> ids) {
550	        return changeAll(user, sheetId, ids, ClaimStatus.OPEN);
551	    }
552	
553	    /** Settle the given claims of the sheet one at a time, in list order, each as {@link #changeStatus} would
554	     * settle it on its own: one a clerk sends PENDING counts as settled; one that cannot be settled (or is not on
555	     * the sheet) is refused and left as it is. */
556	    public OpenedAll settleAll(String user, String sheetId, List<Long> ids) {
557	        return changeAll(user, sheetId, ids, ClaimStatus.SETTLED);
558	    }
559	
560	    /** Move the given claims to a status one at a time, in list order: people in the order they were added, each
561	     * one's claims newest first, each in its own transaction; one that is refused is left as it is. */
562	    private OpenedAll changeAll(String user, String sheetId, List<Long> ids, ClaimStatus next) {
563	        Set<Long> wanted = new HashSet<>(ids);
564	        List<Claim> chosen = transaction.execute(status -> {
565	            sheets.today(sheetId); // the sheet must exist
566	            Map<Long, Integer> personOrder = new HashMap<>();
567	            for (Person person : people.findBySheetIdOrderByIdAsc(sheetId)) {
568	                personOrder.put(person.getId(), personOrder.size());
569	            }
570	            return claims.findBySheetIdOrderByIdDesc(sheetId).stream()
571	                    .filter(c -> wanted.contains(c.getId()))
572	                    .sorted(Comparator.comparing((Claim c) -> personOrder.getOrDefault(c.getPersonId(), Integer.MAX_VALUE)))
573	                    .toList();
574	        });
575	        List<Claim> changed = new ArrayList<>();
576	        for (Claim claim : chosen) {
577	            try {
578	                changed.add(transaction.execute(status -> changeStatus(user, sheetId, claim.getId(), next)));
579	            } catch (ResponseStatusException refused) {
580	                // Left as it is: its transaction rolled back, writing nothing.
581	            }
582	        }
583	        return new OpenedAll(changed.size(), wanted.size() - changed.size(), changed);
584	    }
