586	    /** The sequence a claim in no period is numbered in, with period numbering. */
587	    private static final String NO_PERIOD = "X";
588	
589	    private static final Map<ClaimStatus, String> EVENTS = Map.of(
590	            ClaimStatus.OPEN, "CLAIM_OPENED",
591	            ClaimStatus.PENDING, "CLAIM_PENDING",
592	            ClaimStatus.SETTLED, "CLAIM_SETTLED",
593	            ClaimStatus.VOID, "CLAIM_VOIDED");
594	
595	    /** The figure a claim has now: what it was settled at, else what its person's last statement bound it to,
596	     * else what is due at the rate of the grade its person has on its date; none when that is n/a. */
597	    public BigDecimal figureOf(Claim claim, Person person) {
598	        return rollup.figureOf(claim, person);
599	    }
600	
601	    /** The number a claim opened now takes: the sheet's next number or, with period numbering in force, the next
602	     * in its period's own sequence, <period name>-<n>, or X-<n> for a claim in no period. */
603	    private String nextNumber(String sheetId, Claim claim) {
604	        if (!sheets.numbersByPeriod(sheetId)) {
605	            return String.valueOf(sheets.nextClaimNumber(sheetId));
606	        }
607	        String prefix = periods.periodOf(sheetId, claim.getDate()).map(Period::getName).orElse(NO_PERIOD) + "-";
608	        int last = 0;
609	        for (Claim other : claims.findBySheetIdOrderByIdDesc(sheetId)) {
610	            String number = other.getNumber();
611	            if (number != null && number.startsWith(prefix)) {
612	                String rest = number.substring(prefix.length());
613	                if (rest.matches("\\d{1,9}")) {
614	                    last = Math.max(last, Integer.parseInt(rest));
615	                }
616	            }
617	        }
618	        return prefix + (last + 1);
619	    }
620	
621	    /** The number a claim of this amount corrects: none unless the amount is negative, when it must name a
622	     * SETTLED claim of the same person, or the claim is refused. */
623	    private String correctedBy(String sheetId, Long personId, BigDecimal amount, String corrects) {
624	        if (amount.signum() >= 0) {
625	            return null;
626	        }
627	        String named = corrects == null ? null : corrects.trim();
628	        boolean settled = named != null && claims.findBySheetIdAndPersonId(sheetId, personId).stream()
629	                .anyMatch(c -> named.equals(c.getNumber()) && c.getStatus() == ClaimStatus.SETTLED);
630	        if (!settled) {
631	            throw new ResponseStatusException(HttpStatus.BAD_REQUEST,
632	                    "A correction must name a settled claim of the same person.");
633	        }
634	        return named;
635	    }
