637	    /** Refuse a change to a claim dated in a closed period. Locks the sheet first, so a period cannot close
638	     * while the change is made. */
639	    private void requireOpenPeriod(String sheetId, LocalDate date) {
640	        sheets.lock(sheetId);
641	        periods.requireOpen(sheetId, date);
642	    }
