644	    /** Refuse a claim dated after its person's retirement. */
645	    private static void requireNotRetired(Person person, LocalDate date) {
646	        if (person.retiredOn(date)) {
647	            throw new ResponseStatusException(HttpStatus.UNPROCESSABLE_CONTENT,
648	                    person.getName() + " is retired from " + person.getRetiredFrom() + ".");
649	        }
650	    }
